  function renderTimeAnalytics(){const hours=Object.fromEntries(Array.from({length:24},(_,i)=>[String(i).padStart(2,'0'),0])),days={Mon:0,Tue:0,Wed:0,Thu:0,Fri:0,Sat:0,Sun:0},sessions={Asia:0,London:0,NewYork:0};const names=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];state.trades.forEach(t=>{const d=new Date(t.closedAt*1000),h=d.getUTCHours();hours[String(h).padStart(2,'0')]+=t.net;days[names[d.getUTCDay()]]+=t.net;sessions[h<8?'Asia':h<13?'London':'NewYork']+=t.net});bars('hourBars',hours,Object.keys(hours));bars('dayBars',days,Object.keys(days));bars('sessionBars',sessions,Object.keys(sessions))}
