  function drawTradeOverlays(svg,r){if(!full.length)return;state.trades.forEach(t=>{const ep=xy({time:t.openedAt||t.placedAt,price:t.entry}),xp=xy({time:t.closedAt,price:t.exit});if(!ep||!xp)return;const g=document.createElementNS('http://www.w3.org/2000/svg','g');g.classList.add('trade-marker');const arrow=document.createElementNS('http://www.w3.org/2000/svg','path'),s=t.side==='buy'?1:-1;arrow.setAttribute('d',`M ${ep.x} ${ep.y+10*s} l -5 ${-8*s} h 10 z`);arrow.setAttribute('fill',t.side==='buy'?'#40c78c':'#ed6f76');g.appendChild(arrow);g.appendChild(svgLine(ep.x,ep.y,xp.x,xp.y,'trade-entry'));const ex=document.createElementNS('http://www.w3.org/2000/svg','circle');ex.setAttribute('cx',xp.x);ex.setAttribute('cy',xp.y);ex.setAttribute('r',4);ex.setAttribute('class','trade-exit');g.appendChild(ex);if(t.sl){const y=series.priceToCoordinate(t.sl);if(Number.isFinite(y))g.appendChild(svgLine(ep.x,y,xp.x,y,'trade-sl'))}if(t.tp){const y=series.priceToCoordinate(t.tp);if(Number.isFinite(y))g.appendChild(svgLine(ep.x,y,xp.x,y,'trade-tp'))}g.addEventListener('click',e=>showTradePopup(t,e.clientX,e.clientY));svg.appendChild(g)});state.activeOrders.filter(t=>t.status==='open').forEach(t=>{const ep=xy({time:t.openedAt||t.placedAt,price:t.entry});if(!ep)return;const a=assumptions(),floating=pnl(t,current()),levels=[['sl',t.sl??suggestedBracket(t,'sl'),'trade-sl',!!t.sl],['tp',t.tp??suggestedBracket(t,'tp'),'trade-tp',!!t.tp],['entry',t.entry,'trade-entry',true]];levels.forEach(([f,v,c,active])=>{if(v===null||v===undefined)return;const y=series.priceToCoordinate(v);if(!Number.isFinite(y))return;const visual=svgLine(0,y,r.width,y,c);visual.classList.add('trade-level-visual');if(!active)visual.classList.add('optional-bracket');svg.appendChild(visual);if(f!=='entry'){const hit=svgLine(0,y,r.width,y,'trade-drag-line');hit.dataset.tradeId=t.id;hit.dataset.field=f;hit.classList.add('trade-drag-line');hit.setAttribute('stroke','transparent');hit.setAttribute('stroke-width','16');hit.setAttribute('pointer-events','stroke');svg.appendChild(hit)}const label=svgText(Math.max(70,Math.min(r.width-330,ep.x+18)),y-6,`${f==='entry'?t.lots.toFixed(2)+' '+money(floating,true):bracketLabel(t,f,v,active)}`);label.classList.add('trade-level-label');label.dataset.tradeId=t.id;svg.appendChild(label);if(f!=='entry'){const handle=document.createElement('div');handle.className=`chart-bracket-handle ${c} ${active?'active':'optional'}`;handle.dataset.tradeId=t.id;handle.dataset.field=f;handle.style.top=`${clamp(y,5,r.height-5)}px`;handle.title=`Drag ${active?f.toUpperCase():'ADD '+f.toUpperCase()} to change price`;$('chartStage').appendChild(handle)}});const entryLabel=svgText(Math.max(70,Math.min(r.width-330,ep.x+18)),ep.y-7,`${t.side.toUpperCase()} ${t.lots.toFixed(2)} · ENTRY ${price(t.entry)} · ${money(floating,true)}`);entryLabel.classList.add('position-summary-label');entryLabel.dataset.tradeId=t.id;svg.appendChild(entryLabel)});state.activeOrders.filter(t=>t.status==='pending').forEach(t=>{const y=series.priceToCoordinate(t.requestedEntry);if(!Number.isFinite(y))return;const l=svgLine(0,y,r.width,y,'pending-order-line');l.dataset.pendingId=t.id;l.classList.add('pending-order-line');l.addEventListener('contextmenu',e=>{e.preventDefault();state.activeOrders=state.activeOrders.filter(x=>x.id!==t.id);save();render();toast('Pending order cancelled.','success')});svg.appendChild(l);svg.appendChild(svgText(r.width-110,y-5,`${t.orderType.toUpperCase()} ${price(t.requestedEntry)}`))})}
  function showTradePopup(t,x,y){document.querySelector('.trade-popover')?.remove();const p=document.createElement('div');p.className='trade-popover';p.style.left=`${clamp(x,8,innerWidth-260)}px`;p.style.top=`${clamp(y,75,innerHeight-170)}px`;p.innerHTML=`<strong>${t.side.toUpperCase()} ${money(t.net,true)}</strong><br>Entry ${price(t.entry)} · Exit ${price(t.exit)}<br>${t.reason} · ${t.r.toFixed(2)}R<br>${escape(t.note||'No note')} ${t.tag?`· ${escape(t.tag)}`:''}`;document.body.appendChild(p);setTimeout(()=>p.remove(),5000)}
  function startDrag(e){const el=e.target.closest('.trade-drag-line,.chart-bracket-handle'),proximity=findBracketAtPointer(e),hit=proximity||(el?{id:el.dataset.tradeId,field:el.dataset.field}:null);if(hit){drag={id:hit.id,field:hit.field,moved:false};e.currentTarget.setPointerCapture?.(e.pointerId);e.preventDefault();e.stopPropagation();return}const pending=e.target.closest('.pending-order-line');if(pending){drag={pendingId:pending.dataset.pendingId,field:'pending',moved:false};pending.setPointerCapture?.(e.pointerId);e.preventDefault();e.stopPropagation();return}if(['rectangle','arrow','range','distance'].includes(tool)){drawingDrag=getPoint(e)}}
  function moveDrag(e){if(drag){const p=drag.pendingId?getPoint(e):priceAtPointer(e);if(!p)return;drag.moved=true;if(drag.pendingId){const t=state.activeOrders.find(x=>x.id===drag.pendingId);if(t){t.requestedEntry=p.price;save();redraw();renderOrders()}}else{adjustBracket(drag.id,drag.field,p.price,false);redraw()}return}if(drawingDrag)redraw()}
  function endDrag(e){if(drag){if(drag.moved)suppressClick=true;drag=null;return}if(!drawingDrag)return;const p=getPoint(e);if(!p){drawingDrag=null;return}suppressClick=true;drawings.push({id:uid('drawing'),type:tool,points:[drawingDrag,p]});saveDrawings();drawingDrag=null;redraw();toast('Drag drawing saved.','success')}
  function setSide(s){side=s;$('buyTab').classList.toggle('active',s==='buy');$('sellTab').classList.toggle('active',s==='sell');updateOrderUi()}
  function setOrderType(t){orderType=t;document.querySelectorAll('[data-order-type]').forEach(b=>b.classList.toggle('active',b.dataset.orderType===t));$('entryField').style.display=t==='market'?'none':'block';updateOrderUi()}
  function updateOrderUi(){$('placeOrder').className=`execute-button ${side==='buy'?'buy-execute':'sell-execute'}`;$('placeOrder').innerHTML=`Place ${orderType} ${side} <span>↗</span>`;updatePreview()}
  function updatePreview(){const a=assumptions(),e=orderType==='market'?current():Number($('entryPrice').value),sl=Number($('stopLoss').value),tp=Number($('takeProfit').value);const slValue=Number.isFinite(sl)&&e?pnl({side,entry:e,lots:a.lot},sl)-a.commission*a.lot:0,tpValue=Number.isFinite(tp)&&e?pnl({side,entry:e,lots:a.lot},tp)-a.commission*a.lot:0,rr=Number.isFinite(sl)&&Number.isFinite(tp)&&Math.abs(e-sl)?Math.abs(tp-e)/Math.abs(e-sl):0;$('slPreview').textContent=Number.isFinite(sl)&&e?money(slValue,true):'—';$('tpPreview').textContent=Number.isFinite(tp)&&e?money(tpValue,true):'—';$('rrPreview').textContent=rr?`1:${rr.toFixed(2)}`:'—'}
  function toggleOneClick(){oneClick=!oneClick;$('oneClickToggle').textContent=`One-Click: ${oneClick?'ON':'OFF'}`;$('oneClickToggle').className=`header-button ${oneClick?'one-click-on':'one-click-off'}`;toast(`One-click trading ${oneClick?'enabled':'disabled'}.`,oneClick?'success':'')}
  function saveNamedSession(){const name=$('sessionName').value.trim()||`Session ${new Date().toLocaleDateString()}`,sessions=JSON.parse(localStorage.getItem(SESSION_KEY)||'{}');sessions[uid('session')]={name,at:Date.now(),state:JSON.parse(JSON.stringify(state)),drawings:JSON.parse(JSON.stringify(drawings))};const keys=Object.keys(sessions).sort((a,b)=>sessions[b].at-sessions[a].at).slice(0,10),trimmed={};keys.forEach(k=>trimmed[k]=sessions[k]);localStorage.setItem(SESSION_KEY,JSON.stringify(trimmed));refreshSessionPicker();toast(`Saved session: ${name}.`,'success')}
  function refreshSessionPicker(){const sessions=JSON.parse(localStorage.getItem(SESSION_KEY)||'{}');$('sessionPicker').innerHTML='<option value="">Load a saved session…</option>'+Object.entries(sessions).sort((a,b)=>b[1].at-a[1].at).map(([id,s])=>`<option value="${id}">${escape(s.name)} · ${new Date(s.at).toLocaleDateString()}</option>`).join('')}
  function loadNamedSession(){const id=$('sessionPicker').value,sessions=JSON.parse(localStorage.getItem(SESSION_KEY)||'{}'),saved=sessions[id];if(!saved)return toast('Choose a saved session first.','error');state={...defaultState,...saved.state,sessionRestorable:true};drawings=saved.drawings||[];restore();restoreNextLoad=true;fetchData(state.tf);toast(`Loaded session: ${saved.name}.`,'success')}
  function deleteNamedSession(){const id=$('sessionPicker').value;if(!id)return toast('Choose a saved session first.','error');const sessions=JSON.parse(localStorage.getItem(SESSION_KEY)||'{}');delete sessions[id];localStorage.setItem(SESSION_KEY,JSON.stringify(sessions));refreshSessionPicker();toast('Saved session deleted.','success')}
  function exportSession(){download(new Blob([JSON.stringify({state,drawings,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),'xauusd-backtest-session.json')}
  function chartQuickOrder(s){if(!full.length)return toast('No historical data is loaded for this timeframe.','error');side=s;orderType='market';setSide(s);setOrderType('market');$('entryPrice').value='';$('stopLoss').value='';$('takeProfit').value='';updatePreview();place(true);toast(`${s.toUpperCase()} opened immediately at replay price ${price(current())}. Drag ADD SL / ADD TP on the chart to set optional brackets.`,'success')}
  function quickOrder(s){chartQuickOrder(s)}
  function calculateLots(){const sl=Number($('stopLoss').value),entry=orderType==='market'?current():Number($('entryPrice').value),pct=Number($('riskPercent').value);if(!sl||!entry||!pct)return toast('Enter risk %, entry, and SL first.','error');const lots=(assumptions().balance*pct/100)/(Math.abs(entry-sl)*100);$('lotSize').value=Math.max(.01,lots).toFixed(2);toast(`Lot size set to ${Math.max(.01,lots).toFixed(2)}.`,'success')}
  function exportCsv(){const h=['#','closed_at','side','order_type','entry','exit','lots','gross_pnl','costs','net_pnl','r_multiple','exit_reason','tag','note'],rows=state.trades.map((t,i)=>[i+1,new Date(t.closedAt*1000).toISOString(),t.side,t.orderType,t.entry,t.exit,t.lots,t.gross,t.costs,t.net,t.r,t.reason,t.tag||'',t.note||''].map(v=>`"${String(v).replace(/"/g,'""')}"`).join(','));download(new Blob([[h.join(','),...rows].join('\n')],{type:'text/csv'}),'xauusd-backtest-trades.csv')}
