    document.querySelectorAll('#timeframes button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#timeframes button').forEach(x=>x.classList.toggle('active',x===b));const cursorTime=full[state.cursor]?.time??state.replayCursorTime??dateToTime(state.selectedReplayDate),startTime=full[state.sessionStart]?.time??state.sessionStartTime??cursorTime;state.replayCursorTime=cursorTime;state.sessionStartTime=startTime;state.sessionRestorable=true;fetchData(b.dataset.tf)}));
    $('zoomIn').addEventListener('click',()=>{barSpacing=Math.min(24,barSpacing*1.25);chart?.timeScale().applyOptions({barSpacing})});$('zoomOut').addEventListener('click',()=>{barSpacing=Math.max(3,barSpacing/1.25);chart?.timeScale().applyOptions({barSpacing})});$('resetView').addEventListener('click',()=>chart?.timeScale().fitContent());$('goStart').addEventListener('click',()=>setCursor(state.sessionStart,false));$('replayProgress').addEventListener('input',e=>setCursor(Number(e.target.value),false));$('volumeToggle').addEventListener('change',e=>{volumeVisible=e.target.checked;render()});$('oneClickToggle').addEventListener('click',toggleOneClick);$('stepBack').addEventListener('click',()=>step(-1));$('stepForward').addEventListener('click',()=>step(1));$('playPause').addEventListener('click',togglePlay);$('jumpSession').addEventListener('click',jumpSession);$('jumpNextSession').addEventListener('click',jumpSession);$('jumpEnd').addEventListener('click',()=>setCursor(full.length-1));$('randomStart').addEventListener('click',randomStart);$('goToDate').addEventListener('click',goToDate);$('resetSession').addEventListener('click',resetSession);$('newSession').addEventListener('click',newSession);$('replaySpeed').addEventListener('change',()=>{if(state.isPlaying){clearInterval(timer);state.isPlaying=false;togglePlay()}});$('buyTab').addEventListener('click',()=>setSide('buy'));$('sellTab').addEventListener('click',()=>setSide('sell'));document.querySelectorAll('[data-sidebar-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-sidebar-tab]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('[data-sidebar-section]').forEach(x=>x.classList.toggle('hidden',x.dataset.sidebarSection!==b.dataset.sidebarTab));}));document.querySelectorAll('[data-order-type]').forEach(b=>b.addEventListener('click',()=>setOrderType(b.dataset.orderType)));$('placeOrder').addEventListener('click',place);['entryPrice','stopLoss','takeProfit','lotSize','riskPercent'].forEach(id=>$(id).addEventListener('input',updatePreview));$('quickBuy').addEventListener('click',()=>chartQuickOrder('buy'));$('quickSell').addEventListener('click',()=>chartQuickOrder('sell'));$('chartQuickBuy').addEventListener('click',()=>chartQuickOrder('buy'));$('chartQuickSell').addEventListener('click',()=>chartQuickOrder('sell'));$('calculateLots').addEventListener('click',calculateLots);document.querySelectorAll('#tradesTab th').forEach((th,i)=>th.addEventListener('click',()=>{if(sortColumn===i)sortDirection*=-1;else{sortColumn=i;sortDirection=1}renderLog()}));['startingBalance','lotSize','spreadPoints','slippagePoints','commission','pointSize'].forEach(id=>$(id).addEventListener('change',()=>{state.startingBalance=assumptions().balance;state.lotSize=assumptions().lot;save();updateAnalytics()}));$('activeOrders').addEventListener('click',e=>{const close=e.target.closest('[data-close-id]');if(close){const pct=Number($(`[data-partial-id="${close.dataset.closeId}"]`)?.value||100);closeManual(close.dataset.closeId,pct)}const be=e.target.closest('[data-be-id]');if(be)breakeven(be.dataset.beId)});$('activeOrders').addEventListener('change',e=>{const b=e.target.closest('[data-bracket]');if(b)adjustBracket(b.dataset.id,b.dataset.bracket,Number(b.value))});document.querySelectorAll('.tool-button').forEach(b=>b.addEventListener('click',()=>selectTool(b.dataset.tool)));$('deleteDrawing').addEventListener('click',()=>{drawings=drawings.filter(d=>d.id!==contextId);saveDrawings();redraw();$('contextMenu').hidden=true});document.addEventListener('click',e=>{if(!e.target.closest('.context-menu'))$('contextMenu').hidden=true;if(!e.target.closest('.trade-popover')&&!e.target.closest('.trade-marker'))document.querySelector('.trade-popover')?.remove()});$('resultsToggle').addEventListener('click',()=>$('resultsPanel').classList.toggle('collapsed'));document.querySelectorAll('[data-results-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-results-tab]').forEach(x=>x.classList.toggle('active',x===b));['overview','equity','time','calendar','trades'].forEach(t=>$(`${t}Tab`).classList.toggle('hidden',b.dataset.resultsTab!==t))}));['tradeSideFilter','tradeResultFilter','tradeTagFilter'].forEach(id=>$(id).addEventListener('change',renderLog));$('toggleAssumptions').addEventListener('click',()=>{document.querySelector('.assumptions-card').classList.toggle('collapsed');$('toggleAssumptions').textContent=document.querySelector('.assumptions-card').classList.contains('collapsed')?'⌄':'⌃'});$('settingsButton').addEventListener('click',()=>{$('settingsBackdrop').hidden=false;requestAnimationFrame(()=>$('settingsDrawer').classList.add('open'))});$('dataApiKey').value=CONFIG.TWELVE_DATA_KEY;$('dataApiKey').addEventListener('change',()=>{CONFIG.TWELVE_DATA_KEY=$('dataApiKey').value.trim();localStorage.setItem('aurum-twelve-data-key',CONFIG.TWELVE_DATA_KEY);updateApiStatus();state.cursor=null;state.sessionStart=null;fetchData(currentTf)});$('metalsApiKey').value=CONFIG.METALS_API_KEY;$('metalsApiKey').addEventListener('change',()=>{CONFIG.METALS_API_KEY=$('metalsApiKey').value.trim();localStorage.setItem('aurum-metals-api-key',CONFIG.METALS_API_KEY);state.cursor=null;state.sessionStart=null;fetchData(currentTf)});updateApiStatus();$('oneClickSL').value=localStorage.getItem('aurum-one-click-sl')||200;$('oneClickTP').value=localStorage.getItem('aurum-one-click-tp')||400;$('oneClickConfirm').checked=localStorage.getItem('aurum-one-click-confirm')!=='false';['oneClickSL','oneClickTP','oneClickConfirm'].forEach(id=>$(id).addEventListener('change',()=>{localStorage.setItem(`aurum-${id.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())}`,$(id).type==='checkbox'?$(id).checked:$(id).value)}));$('toggleToolbar').addEventListener('click',()=>{$('drawingToolbar').classList.toggle('collapsed');$('toggleToolbar').textContent=$('drawingToolbar').classList.contains('collapsed')?'≫':'≪'});$('closeSettings').addEventListener('click',closeSettings);$('settingsBackdrop').addEventListener('click',closeSettings);$('downloadCsv').addEventListener('click',exportCsv);$('exportCsv').addEventListener('click',exportCsv);$('saveSession').addEventListener('click',saveNamedSession);$('loadSession').addEventListener('click',loadNamedSession);$('deleteSession').addEventListener('click',deleteNamedSession);$('exportSession').addEventListener('click',exportSession);$('sessionPicker').addEventListener('change',loadNamedSession);$('screenshotButton').addEventListener('click',screenshot);$('shortcutButton').addEventListener('click',()=>{$('shortcutSheet').hidden=!$('shortcutSheet').hidden});$('exportStatsPdf').addEventListener('click',exportPdf);$('clearSession').addEventListener('click',()=>{if(confirm('Clear this backtest session, trade log, and drawings?')){localStorage.removeItem(STATE_KEY);localStorage.removeItem(DRAW_KEY);state={...defaultState,startingBalance:assumptions().balance};drawings=[];resetSession();closeSettings()}});document.addEventListener('keydown',e=>{const tag=document.activeElement?.tagName;if(['INPUT','SELECT','TEXTAREA'].includes(tag))return;if(e.key===' '){e.preventDefault();togglePlay()}else if(e.key==='ArrowRight')step(1);else if(e.key==='ArrowLeft')step(-1);else if(e.key==='Escape'){selectTool('cursor');$('shortcutSheet').hidden=true;document.querySelector('.trade-popover')?.remove()}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();const last=drawings.pop();if(last){saveDrawings();redraw();toast('Last drawing undone.')}}else if(e.key.toLowerCase()==='d')$('drawingToolbar').classList.toggle('collapsed');else if(e.key.toLowerCase()==='b')setSide('buy');else if(e.key.toLowerCase()==='s')setSide('sell');else if(e.key.toLowerCase()==='h')selectTool('horizontal');else if(e.key.toLowerCase()==='t')selectTool('trend');else if(e.key.toLowerCase()==='f')selectTool('fibonacci');else if(/^[1-7]$/.test(e.key)){const key=['1m','5m','15m','30m','1h','4h','1d'][Number(e.key)-1];document.querySelector(`#timeframes [data-tf="${key}"]`)?.click()}})
